"""Render docs/architecture/*.md from templates, filling example data from the captured payloads.

    uv run python docs/build/architecture.py   # render docs/architecture/*.md (make docs)

Templates live in docs/build/architecture/*.md. A placeholder on its own line,

    {{example file.json path [trim=N] [keys=a,b] [lang=json]}}

becomes a fenced block holding the value at `path` (dot-separated keys and list indexes; `.` for the whole
file). `trim` shortens long strings (signatures, hashes) so a block stays readable; `keys` keeps only
those keys of an object. An inline `{{value file.json path}}` becomes the bare value.

    {{code path/to/file.py Qualified.name [start="text"] [end="text"]}}

becomes the current source of that function or class, with a link to its lines; `start` and `end` cut it to the
lines from the first one containing `start` through the next one containing `end`.

    {{table file.json path cols=a,b,c [rows=0,2] [trim=N]}}

becomes a Markdown table of the list at `path` (or only the listed items), one row per item, with the named
columns. Unix times are shown
in UTC. A placeholder that names a missing path, symbol, column or marker fails the build, so the documents
never show data the system did not produce or code that no longer exists.
"""

from __future__ import annotations

import ast
import datetime
import json
import re
import shlex
import textwrap
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
TEMPLATES = Path(__file__).resolve().parent / "architecture"
OUT = ROOT / "docs" / "architecture"
EXAMPLES = OUT / "examples"
BLOCK = re.compile(r"^\{\{example (.+?)\}\}$", re.MULTILINE)
INLINE = re.compile(r"\{\{value (.+?)\}\}")
CODE = re.compile(r"^\{\{code (.+?)\}\}$", re.MULTILINE)
TABLE = re.compile(r"^\{\{table (.+?)\}\}$", re.MULTILINE)
HEADER = "<!-- Generated by docs/build/architecture.py from docs/build/architecture/{name}; edit the template. -->\n"


def lookup(spec: str) -> tuple[Any, dict[str, str]]:
    parts = shlex.split(spec)
    file, path, opts = parts[0], parts[1], dict(p.split("=", 1) for p in parts[2:])
    value: Any = json.loads((EXAMPLES / file).read_text())
    if path != ".":
        for key in path.split("."):
            value = value[int(key)] if isinstance(value, list) else value[key]
    return value, opts


def trim(value: Any, n: int) -> Any:
    if isinstance(value, str):
        return value if len(value) <= n else value[:n] + "…"
    if isinstance(value, list):
        return [trim(v, n) for v in value]
    if isinstance(value, dict):
        return {k: trim(v, n) for k, v in value.items()}
    return value


def block(match: re.Match) -> str:
    value, opts = lookup(match[1])
    if "keys" in opts:
        value = {k: value[k] for k in opts["keys"].split(",")}
    if "trim" in opts:
        value = trim(value, int(opts["trim"]))
    lang = opts.get("lang", "json")
    text = (
        value
        if isinstance(value, str) and lang != "json"
        else json.dumps(value, indent=2, ensure_ascii=False)
    )
    return f"```{lang}\n{text}\n```"


def inline(match: re.Match) -> str:
    value, opts = lookup(match[1])
    if "trim" in opts:
        value = trim(value, int(opts["trim"]))
    return value if isinstance(value, str) else json.dumps(value)


def source(rel: str, symbol: str, start: str | None = None, end: str | None = None) -> tuple[str, int, int]:
    """The source of ``symbol`` in ``rel``, optionally cut to the lines from the first containing ``start``
    through the next containing ``end``. Returns (dedented text, first line, last line)."""
    lines = (ROOT / rel).read_text().splitlines()
    node: ast.AST = ast.parse("\n".join(lines))
    for part in symbol.split("."):
        node = next(
            n
            for n in ast.iter_child_nodes(node)
            if isinstance(n, ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef) and n.name == part
        )
    first = min([node.lineno, *(d.lineno for d in getattr(node, "decorator_list", []))])
    last = node.end_lineno
    if start:
        first = next(i for i in range(first, last + 1) if start in lines[i - 1])
    if end:
        last = next(i for i in range(first, last + 1) if end in lines[i - 1])
    return textwrap.dedent("\n".join(lines[first - 1 : last])), first, last


def code(match: re.Match) -> str:
    parts = shlex.split(match[1])
    rel, symbol, opts = parts[0], parts[1], dict(p.split("=", 1) for p in parts[2:])
    body, first, last = source(rel, symbol, opts.get("start"), opts.get("end"))
    link = f"../../{rel}#L{first}-L{last}"
    return f"[`{rel}` · `{symbol}` · lines {first}–{last}]({link})\n\n```python\n{body}\n```"


def cell(value: Any, n: int) -> str:
    if isinstance(value, float) and 1.5e9 < value < 2.5e9:  # a Unix time
        stamp = datetime.datetime.fromtimestamp(value, datetime.UTC)
        text = stamp.strftime("%Y-%m-%d %H:%M:%S.%f")[:-4] + "Z"
    else:
        text = trim(value if isinstance(value, str) else json.dumps(value, ensure_ascii=False), n)
    text = text.replace("|", "\\|")
    return f"`{text}`" if text else ""


def table(match: re.Match) -> str:
    rows, opts = lookup(match[1])
    if "rows" in opts:
        rows = [rows[int(i)] for i in opts["rows"].split(",")]
    cols = opts["cols"].split(",")
    n = int(opts.get("trim", 40))
    lines = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    lines += ["| " + " | ".join(cell(row[c], n) for c in cols) + " |" for row in rows]
    return "\n".join(lines)


def render() -> dict[str, str]:
    """Every page, by file name, as it would be written."""
    pages = {}
    for template in sorted(TEMPLATES.glob("*.md")):
        text = CODE.sub(code, template.read_text())
        text = TABLE.sub(table, text)
        text = BLOCK.sub(block, text)
        text = INLINE.sub(inline, text)
        pages[template.name] = HEADER.format(name=template.name) + text.rstrip("\n") + "\n"
    return pages


def main() -> None:
    for name, text in render().items():
        (OUT / name).write_text(text)
        print(f"  wrote docs/architecture/{name}")


if __name__ == "__main__":
    main()
